import React from 'react'
import { connect } from 'react-redux'
import {
  Form,
  Input,
  Button,
  Modal,
  Alert,
  Radio,
  Card,
  Collapse,
  Icon,
  Checkbox
} from 'antd'
import PropTypes from 'prop-types'
import { get } from 'lodash'
import GoPassengerClaimModalWrapper from './goPassengerClaimModal.style'
import claimActions from '../../redux/claims/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import PermissionChecker from '../../../components/permissionChecker'

const Panel = Collapse.Panel
const RadioGroup = Radio.Group
const FormItem = Form.Item

const { resetReduxStateClaim, postGoPassengerOrder, postGoPassengerClaim } = claimActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class GoPassengerClaimModal extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      typingTimeout: 0,
      orderId: '',
      benefitId: '',
      displaySafeScreen: false,
      displayLimitAlert: false,
      skipPrecheck: false,
      isOrderSubmitted: false,
      requestId: 0
    }
    this.initState = this.state
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { displaySafeScreen, displayLimitAlert } = nextProps
    if (displaySafeScreen) {
      this.setState({ displaySafeScreen: true })
    }
    if (displayLimitAlert) {
      this.setState({ displayLimitAlert: true })
    }
  }

  componentDidMount () {
    this.resetState()
  }

  componentDidUpdate (prevProps) {
    const { orderResult, postGoPassengerOrderError } = this.props
    const prevOrderResult = prevProps.orderResult
    if (orderResult.requestId !== this.state.requestId) {
      return
    }
    if (get(orderResult, 'name') !== get(prevOrderResult, 'name') ||
        get(orderResult, 'email') !== get(prevOrderResult, 'email')) {
      this.props.form.setFieldsValue({
        name: get(orderResult, 'name', ''),
        email: get(orderResult, 'email', '')
      })
    }
    if (postGoPassengerOrderError && !prevProps.postGoPassengerOrderError) {
      this.setState({ isOrderSubmitted: false })
    }
  }

  resetState = () => {
    if (this.state.typingTimeout) {
      clearTimeout(this.state.typingTimeout)
    }
    this.setState(this.initState)
    this.props.resetReduxStateClaim(['orderResult', 'orderStatus'])
    this.props.resetLoadingRedux(['POST_GO_PASSENGER_ORDER', 'POST_GO_PASSENGER_CLAIM'])
    this.props.resetErrorRedux(['POST_GO_PASSENGER_ORDER', 'POST_GO_PASSENGER_CLAIM'])
  };

  async validateForm () {
    return new Promise(resolve => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form, orderResult } = this.props

    const formValues = form.getFieldsValue()
    const userId = orderResult.user_id
    const phoneNumber = orderResult.phone_number
    let payload = {
      ...formValues,
      email: formValues.email || '',
      gojek_product: this.props.gojekProduct
    }

    if (userId && phoneNumber) {
      payload = {
        ...payload,
        phone_number: phoneNumber,
        user_id: userId
      }
    }
    this.setState({
      orderId: payload.order_id,
      isOrderSubmitted: true
    }, () => {
      this.props.postGoPassengerOrder(payload)
    })
  }

  onValidateClaim = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { orderResult, gojekProduct } = this.props
    const { orderId, benefitId, skipPrecheck } = this.state
    const payload = {
      order_id: orderId,
      user_id: get(orderResult, 'user_id'),
      benefit_id: benefitId,
      skip_precheck: skipPrecheck,
      gojek_product: gojekProduct
    }
    this.props.validate(payload)
  }

  onChangeBenefit = val => {
    this.props.resetValidateStatus()
    this.setState({ benefitId: val.target.value })
  }

  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.resetState()
  }

  scheduleOrderCheck = () => {
    if (this.state.typingTimeout) {
      clearTimeout(this.state.typingTimeout)
    }
    this.setState({
      typingTimeout: setTimeout(() => {
        const phone = this.props.form.getFieldValue('phone_number')
        const orderId = this.props.form.getFieldValue('order_id')
        if (phone && orderId) {
          const requestId = this.state.requestId + 1
          this.setState({ requestId })
          this.props.postGoPassengerOrder({ phone_number: phone, order_id: orderId, skip_benefits: true, requestId })
        } else {
          this.props.form.setFieldsValue({ name: '', email: '' })
          this.props.resetReduxStateClaim(['orderResult', 'orderStatus', 'goPassengerOrderLoading'])
        }
      }, 600)
    })
  }

  backToBenefit = () => {
    this.resetState()
    this.props.resetSafeScreen()
  }

  genExtra = () => (<Icon type='down' />)

  isActive = status => {
    this.setState({ isClaimActive: status })
  }

  onCheckChange = (e) => {
    this.setState({ skipPrecheck: e.target.checked })
  }

  noBenefitInfo = () => {
    return (
      <div>
        <Card>
          <h3>Anda dalam perlindungan yang tepat</h3>
          <p>
            Untuk info lebih lengkap hubungi customer service kami pada nomor di bawah ini &amp; daftarkan klaim anda
          </p>
          <span style={{
            fontSize: '24px'
          }}
          >
            <i className='fas fa-phone-volume' />
            &nbsp;&nbsp;021 3044 8080
          </span>
          <br />
          <br />
          - ATAU -
          <br />
          <br />
          <p>
            Chat dengan customer service kami melalu nomor whatsapp dibawah ini &amp; daftarkan klaim anda
          </p>
          <span style={{
            fontSize: '24px'
          }}
          >
            <i className='fab fa-whatsapp' />
            &nbsp;&nbsp;0877 0017 8000
          </span>
        </Card>
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          marginTop: '20px'
        }}
        >
          <Button type='primary' onClick={() => this.backToBenefit()}>
            Back
          </Button>
        </div>
      </div>
    )
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const {
      orderResult,
      orderStatus,
      postGoPassengerOrderLoading,
      postGoPassengerOrderError,
      goPassengerBenefits,
      getGoPassengerBenefitsLoading,
      getGoPassengerBenefitsError,
      goPassengerBenefitsStatus,
      goPassengerClaimLoading,
      goPassengerClaimError,
      goPassengerClaimStatus,
      permissions,
      gojekProduct
    } = this.props

    const { benefitId, isClaimActive, skipPrecheck, isOrderSubmitted } = this.state
    return (
      <GoPassengerClaimModalWrapper>
        <Modal
          visible={this.props.isOpen}
          onCancel={this.handleCancel}
          footer={null}
          title={`Create ${gojekProduct === 'go-driver' ? 'Go-Driver' : 'Go-Passenger'} Claim`}
          maskClosable={false}
          wrapClassName='benefits-modal'
        >
          <div className='go-passenger'>
            {postGoPassengerOrderError && !postGoPassengerOrderLoading && (<Alert message={orderStatus} type='error' />)}
            {goPassengerClaimError && !goPassengerClaimLoading && (<Alert message={goPassengerClaimStatus} type='error' />)}
            {getGoPassengerBenefitsError && !getGoPassengerBenefitsLoading && (<Alert message={goPassengerBenefitsStatus} type='error' />)}
            {benefitId && !isClaimActive && (<Alert message='Claim is not active for this benefit' type='error' />)}
            {
              isOrderSubmitted && orderResult.user_id && !postGoPassengerOrderError && !postGoPassengerOrderLoading
                ? (
                  <Form
                    id='event-form'
                    onSubmit={(e) => this.onValidateClaim(e)}
                    style={{
                      marginTop: '10px'
                    }}
                  >
                    <label>
                      <strong style={{
                        padding: '20px 0'
                      }}
                      >Choose a benefit:
                      </strong>
                    </label>
                    <FormItem validateStatus='validateStatus'>
                      {
                        getFieldDecorator('benefit_id', {
                          rules: [
                            {
                              required: true,
                              message: 'Please select a benefit'
                            }
                          ]
                        })(
                          <RadioGroup value={benefitId} onChange={(e) => this.onChangeBenefit(e)} className='benefits-radio'>
                            {
                              goPassengerBenefits.map((val, index) => {
                                if (val.benefits) {
                                  if (val.benefits.length > 1) {
                                    return (
                                      <Collapse key={index}>
                                        <Panel
                                          header={
                                            <div className='benefits-collapse-header'>
                                              <b>{val.benefit_group_name}</b>
                                              <br />
                                              <span>{val.benefit_group_description}</span>
                                            </div>
                                          } key={index} extra={this.genExtra()}
                                        >
                                          {
                                            val.benefits.map((value, i) => {
                                              return (
                                                <Radio key={i} value={value.benefit_id} onChange={() => this.isActive(value.is_claim_active)}>
                                                  <b>{value.benefit_name}</b>
                                                </Radio>
                                              )
                                            })
                                          }
                                        </Panel>
                                      </Collapse>
                                    )
                                  } else {
                                    return val.benefits.map((value, i) => {
                                      return (
                                        <div key={i} className='radio-content-wrapper'>
                                          <Radio key={i} value={value.benefit_id} onChange={() => this.isActive(value.is_claim_active)}>
                                            <b>{value.benefit_name}</b>
                                            <br />
                                            <span className='description'>{value.description}</span>
                                          </Radio>
                                          <br />
                                        </div>
                                      )
                                    })
                                  }
                                } else {
                                  return (
                                    <div key={index} className='radio-content-wrapper'>
                                      <Radio key={index} value={val.benefit_id} onChange={() => this.isActive(val.is_claim_active)}>
                                        <b>{val.benefit_name}</b>
                                        <br />
                                        <span className='description'>{val.description}</span>
                                      </Radio>
                                      <br />
                                    </div>
                                  )
                                }
                              })
                            }
                          </RadioGroup>
                        )
                      }
                    </FormItem>
                    <PermissionChecker permissionGetter={permissions} permissionSetter='ops.claims_skip_precheck'>
                      <Checkbox
                        style={{
                          margin: '15px'
                        }} defaultValue={skipPrecheck} onChange={(e) => this.onCheckChange(e)}
                      >Skip Precheck
                      </Checkbox>
                    </PermissionChecker>
                    <FormItem>
                      <Button
                        form='event-form' className='button' key='submit' type='primary' htmlType='submit' style={{
                          float: 'right',
                          marginTop: '20px'
                        }} loading={goPassengerClaimLoading} disabled={!isClaimActive}
                      >
                        Create claim
                      </Button>
                    </FormItem>
                  </Form>)
                : (
                  <Form
                    id='event-form'
                    onSubmit={(e) => this.onSubmit(e)}
                    style={{
                      marginTop: '10px'
                    }}
                  >
                    <label>
                      <strong style={{
                        padding: '20px 0'
                      }}
                      >
                        Customer Phone Number:
                      </strong>
                    </label>
                    <FormItem validateStatus='validateStatus'>
                      {
                        getFieldDecorator('phone_number', {
                          rules: [
                            {
                              required: true,
                              message: 'Phone number cannot be empty'
                            }, {
                              pattern: /^\+\d{7,15}$/,
                              message: 'Invalid phone number, format: +[country code][phone number without leading zero]'
                            }
                          ]
                        })(<Input onChange={() => this.scheduleOrderCheck()} placeholder='+62812345678' />)
                      }
                    </FormItem>
                    <label>
                      <strong style={{
                        padding: '20px 0'
                      }}
                      >Customer Order Id:
                      </strong>
                    </label>
                    <FormItem>
                      {
                        getFieldDecorator('order_id', {
                          rules: [
                            {
                              required: true,
                              message: 'Order ID cannot be empty'
                            }, {
                              pattern: /^[A-Za-z0-9-_ ]+$/,
                              message: 'Invalid order id'
                            }
                          ]
                        })(<Input onChange={() => this.scheduleOrderCheck()} />)
                      }
                    </FormItem>
                    <label>
                      <strong style={{
                        padding: '20px 0'
                      }}
                      >Customer Name:
                      </strong>
                    </label>
                    <FormItem>
                      {
                        getFieldDecorator('name', {
                          rules: [
                            {
                              required: true,
                              message: 'Name cannot be empty'
                            }
                          ]
                        })(<Input disabled suffix={postGoPassengerOrderLoading ? <Icon type='loading' spin /> : null} />)
                      }
                    </FormItem>
                    <label>
                      <strong style={{
                        padding: '20px 0'
                      }}
                      >Customer Email:
                      </strong>
                    </label>
                    <FormItem>
                      {
                        getFieldDecorator('email', {
                          initialValue: '',
                          rules: [
                            {
                              type: 'email',
                              message: 'Email not valid'
                            }
                          ]
                        })(<Input disabled suffix={postGoPassengerOrderLoading ? <Icon type='loading' spin /> : null} />)
                      }
                    </FormItem>
                    <FormItem>
                      <Button
                        form='event-form' className='button' key='submit' type='primary' htmlType='submit' style={{
                          float: 'right',
                          marginTop: '20px'
                        }}
                        loading={postGoPassengerOrderLoading}
                        disabled={!orderResult.name}
                      >
                        Save
                      </Button>
                    </FormItem>
                  </Form>)
            }
          </div>
        </Modal>
      </GoPassengerClaimModalWrapper>
    )
  }
}

const WrappedGoPassengerClaimModal = Form.create()(GoPassengerClaimModal)

WrappedGoPassengerClaimModal.propTypes = {
  orderResult: PropTypes.object.isRequired,
  goPassengerBenefits: PropTypes.array.isRequired
}

WrappedGoPassengerClaimModal.defaultProps = {
  orderResult: {},
  goPassengerBenefits: []
}

export default connect(state => ({
  orderResult: state.Claims.orderResult,
  orderStatus: state.Claims.orderStatus,
  goPassengerBenefits: state.Claims.goPassengerBenefits,
  goPassengerBenefitsStatus: state.Claims.goPassengerBenefitsStatus,
  goPassengerClaim: state.Claims.goPassengerClaim,
  goPassengerClaimStatus: state.Claims.goPassengerClaimStatus,
  postGoPassengerOrderLoading: state.Claims.goPassengerOrderLoading,
  postGoPassengerOrderError: state.Error.POST_GO_PASSENGER_ORDER,
  getGoPassengerBenefitsLoading: state.Loading.GET_GO_PASSENGER_BENEFITS,
  getGoPassengerBenefitsError: state.Error.GET_GO_PASSENGER_BENEFITS,
  goPassengerClaimLoading: state.Loading.POST_GO_PASSENGER_CLAIM,
  goPassengerClaimError: state.Error.POST_GO_PASSENGER_CLAIM
}), {
  postGoPassengerOrder,
  postGoPassengerClaim,
  resetReduxStateClaim,
  resetLoadingRedux,
  resetErrorRedux
})(WrappedGoPassengerClaimModal)
