import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Icon, Button, Tag } from 'antd'
import PropTypes from 'prop-types'
import moment from 'moment'
import swal from 'sweetalert2'
import QueryString from 'query-string'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import PermissionChecker from '../../../components/permissionChecker'
import GoPassengerClaimModal from './goPassengerClaimModal'
import TableWrapper from './pagination.style'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'
import claimActions from '../../redux/claims/actions'
import policyActions from '../../../redux/policy/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import teamAction from '../../redux/team/actions'
import getClaimColumns from './utility/claimColumns'
import {
  getColumnProps as helperGetColumnProps,
  getOwnerColumnProps as helperGetOwnerColumnProps,
  getPartnerColumnProps as helperGetPartnerColumnProps,
  triggerFiltersWithKey as helperTriggerFiltersWithKey,
  buildFilterParams as helperBuildFilterParams,
  extractProductKeyFromId as helperExtractProductKeyFromId,
  getPartnerProductIdFromUrl as helperGetPartnerProductIdFromUrl,
  getPackageNameFromUrl as helperGetPackageNameFromUrl,
  getProductNamefromKey as helperGetProductNamefromKey
  , fetchFiltersFromClaimsFilter as helperFetchFiltersFromClaimsFilter
} from './utility/claimFilterHelpers'

const {
  getClaimLists,
  getClaimFilters,
  resetReduxStateClaim,
  exportClaimsReport,
  validateClaimGoPassenger,
  resetValidateStatus,
  postGoPassengerClaim,
  getClaimUsers
} = claimActions
const { getPartners, getProducts } = policyActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
const { getListGroups } = teamAction

class ClaimLists extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      data: [],
      loading: false,
      failedMessage: '',
      userEmail: '',
      permissions: [],
      searchTextQuery: {},
      isChange: false,
      filteredInfo: {},
      claimsFilter: {},
      showGoPassengerClaimModal: false,
      groups: [],
      displaySafeScreen: false,
      validatePopupMessage: '',
      displayLimitAlert: false,
      validateClaimGoPassengerStatus: '',
      payload: {},
      gojekProduct: undefined,
      startDate: '',
      endDate: '',
      isLoadingFilters: false,
      lastProductKeyRequested: null,
      lastPackageNameRequested: null
    }
  }

  fetch = (params = {}) => {
    const {
      page: pageParam,
      page_size: pageSizeParam
    } = params
    const page = Number(pageParam) || 1
    const pageSize = Number(pageSizeParam) || 50
    delete params.page
    delete params.page_size
    this.setState({ page_size: pageSize, page, claimsFilter: params, searchTextQuery: params })

    this.props.getListGroups()
    this.props.getClaimUsers()
    /**
     *  {created_at} is being added in the param in filter in claims listing if there are only two params
     *   i.e. page_size and page otherwise no created_at filter is not added in params
     */
    let createdAt
    if (Object.keys(params).length === 0) {
      createdAt = [moment().subtract(1, 'days').format('YYYY-MM-DD'), moment().format('YYYY-MM-DD')]
    }
    this.props.getClaimLists({
      page,
      page_size: pageSize,
      created_at: createdAt,
      ...params
    })
  }

  triggerFiltersWithKey (key, type) {
    return helperTriggerFiltersWithKey(this, key, type)
  }

  buildFilterParams (extractedKey, type) {
    return helperBuildFilterParams(this, extractedKey, type)
  }

  extractProductKeyFromId (partnerproductId) {
    return helperExtractProductKeyFromId(this, partnerproductId)
  }

  getPartnerProductIdFromUrl (search) {
    return helperGetPartnerProductIdFromUrl(search)
  }

  getPackageNameFromUrl (search) {
    return helperGetPackageNameFromUrl(search)
  }

  getPartnerColumnProps (key) {
    return helperGetPartnerColumnProps(this, key)
  }

  componentDidUpdate (prevProps) {
    const { location, filtersData, getClaimFilters } = this.props
    const { isLoadingFilters } = this.state

    const currentPartnerProductId = this.getPartnerProductIdFromUrl(location?.search)
    const prevPartnerProductId = this.getPartnerProductIdFromUrl(prevProps.location?.search)
    const currentPackageName = this.getPackageNameFromUrl(location?.search)
    const prevPackageName = this.getPackageNameFromUrl(prevProps.location?.search)

    // Trigger filters only when partnerproduct_id or package_name changes
    if ((currentPartnerProductId !== prevPartnerProductId || currentPackageName !== prevPackageName) && !isLoadingFilters) {
    // Determine which trigger to call based on what changed
      if (currentPartnerProductId !== prevPartnerProductId && currentPartnerProductId) {
        this.triggerFiltersWithKey(currentPartnerProductId, 'product')
      } else if (currentPackageName !== prevPackageName && currentPackageName) {
        this.triggerFiltersWithKey(currentPackageName, 'package')
      } else if (!currentPartnerProductId && !currentPackageName) {
      // If both are cleared, reset filters
        this.setState({
          isLoadingFilters: true,
          lastProductKeyRequested: null,
          lastPackageNameRequested: null
        })
        getClaimFilters()
      }
    }

    // Handle case where filtersData updates and we have existing filters
    if (filtersData !== prevProps.filtersData && !isLoadingFilters) {
      if (currentPartnerProductId) {
        this.triggerFiltersWithKey(currentPartnerProductId, 'product')
      } else if (currentPackageName) {
        this.triggerFiltersWithKey(currentPackageName, 'package')
      }
    }

    // Reset loading flag when filtersData updates
    if (filtersData !== prevProps.filtersData && isLoadingFilters) {
      this.setState({ isLoadingFilters: false })
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      data,
      getClaimListsStatus,
      getClaimListsError,
      profileData,
      validateClaimGoPassengerStatus,
      dataValidateGocar,
      groupLists,
      claimExportLoading,
      claimExportError,
      claimExportMessage
    } = nextProps
    const { email } = profileData
    const { listGroups } = groupLists
    const { claim_id: claimId, is_claimable: isClaimable, is_first_claim: isFirstClaim, message } = dataValidateGocar
    if (validateClaimGoPassengerStatus !== undefined && validateClaimGoPassengerStatus !== '' && validateClaimGoPassengerStatus === 'success') {
      if (claimId !== null && (isFirstClaim === true || isFirstClaim === false)) {
        const { history } = this.props
        history.push(`/claims/${claimId}`)
      } else if (claimId === null && isFirstClaim === true) {
        this.createClaim()
        this.props.resetValidateStatus()
      } else if (claimId === null && isFirstClaim === false && isClaimable === false) {
        this.setState({ displaySafeScreen: true })
        this.props.resetValidateStatus()
      } else {
        this.createClaim()
        this.setState({ validatePopupMessage: message })
        this.props.resetValidateStatus()
      }
      if (validateClaimGoPassengerStatus !== undefined && validateClaimGoPassengerStatus !== '' && validateClaimGoPassengerStatus === 'Klaim telah terdaftar untuk Nomor pesanan ini') {
        this.setState({ displayLimitAlert: true })
        this.props.resetValidateStatus()
      }
      if (validateClaimGoPassengerStatus !== undefined && validateClaimGoPassengerStatus !== '' && validateClaimGoPassengerStatus !== 'success' && validateClaimGoPassengerStatus !== 'Klaim telah terdaftar untuk Nomor pesanan ini') {
        this.setState({ displaySafeScreen: true })
        this.props.resetValidateStatus()
      }
    }
    if (validateClaimGoPassengerStatus !== undefined && validateClaimGoPassengerStatus !== '' && validateClaimGoPassengerStatus !== 'success') {
      this.setState({ validateClaimGoPassengerStatus })
    }
    if (listGroups !== undefined) {
      this.setState({ groups: listGroups })
    }
    if (email !== undefined) {
      this.setState({ userEmail: email })
    }
    if (!getClaimListsError) {
      this.setState({ data })
    } else {
      this.setState({ data: [], failedMessage: getClaimListsStatus })
    }
    if (!claimExportLoading && claimExportMessage) {
      swal({ type: claimExportError ? 'error' : 'success', title: claimExportError ? 'Error' : 'Success', text: claimExportMessage })
      this.props.resetReduxStateClaim(['claimExportMessage'])
      this.props.resetErrorRedux(['EXPORT_CLAIMS_REPORT'])
    }
  }

  componentDidMount () {
    const { search, state } = this.props.location
    let filters = {}
    if ((state && state.state)) {
      filters = {
        ...search,
        ...state.state
      }
      this.fetch(filters)
    } else {
      const querySearch = QueryString.parse(search)
      this.fetch({
        ...querySearch
      })
    }
    this.props.getPartners()
    this.props.getProducts()
    this.props.getClaimFilters()
  }

  componentWillUnmount () {
    this.props.resetReduxStateClaim()
  }

  handleResetReduxState = () => {
    this.props.resetReduxStateClaim()
  }

  detailPage = id => {
    const { history } = this.props
    const { searchTextQuery } = this.state
    history.push({
      pathname: `/claims/${id}`,
      state: {
        ...searchTextQuery
      }
    })
  }

  onInputChange = (event, identifier) => {
    this.setState({
      searchTextQuery: {
        [identifier]: event.target.value
      },
      isChange: true
    })
  }

  onInputProductChange = (event, identifier) => {
    const { searchTextQuery } = this.state

    this.setState({
      searchTextQuery: {
        ...searchTextQuery,
        [identifier]: event
      },
      isChange: true
    })
  }

  handleProductSearch = () => {
    const { searchTextQuery } = this.state
    const { history, location } = this.props
    const finalFilter = {
      ...searchTextQuery
    }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({ pathname: location.pathname, search: searchQuery })
    if (Object.values(searchTextQuery).length) {
      this.setState({ policy_number: false, claim_no: false, application_no: false, searchTextQuery: finalFilter, partnerproduct_id: false })
      this.fetch(finalFilter)
    }
  }

  onSearch = (e, identifier, filterType) => {
    const { startDate, endDate } = e
    let dateSearch = {}
    if (startDate) {
      this.setState({ startDate: startDate })
    }
    if (endDate) {
      this.setState({ endDate: endDate })
    }
    if (filterType === 'date_range') {
      dateSearch = {
        [`${identifier}`]: [startDate || this.state.startDate, endDate || this.state.endDate]
      }
      this.setState({
        [identifier]: false, // set as not visible
        searchTextQuery: dateSearch,
        isChange: true
      })
    } else {
      e.preventDefault()
    }
    const { searchTextQuery } = this.state
    const { history, location } = this.props
    const finalFilter = {
      ...searchTextQuery,
      ...dateSearch
    }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({ pathname: location.pathname, search: searchQuery })
    if (Object.values(searchTextQuery).length || Object.values(dateSearch).length) {
      this.setState({ policy_number: false, claim_no: false, application_no: false, searchTextQuery: finalFilter })
      this.fetch(finalFilter)
    }
  }

handleResetFilter = () => {
  const { history, location } = this.props
  location.search = ''
  history.push(location.pathname)
  this.setState({
    searchText: '',
    loading: true,
    searchTextQuery: {},
    claimsFilter: {},
    filteredInfo: {},
    clearDate: true
  })
  this.props.resetReduxStateClaim()
  this.props.getClaimFilters()
  this.fetch()
}

  handleTableChange = (pagination, filters, sorter) => {
    const { history, location } = this.props
    const { searchTextQuery } = this.state
    const { pageSize, current } = pagination
    const filterObj = {}
    Object.keys(filters).map((key, index) => {
      let value = filters[key] || []
      value = Array.isArray(value)
        ? value[0]
        : value
      if (value) { filterObj[key] = value }
      return filterObj
    })
    const querySearch = QueryString.parse(location.search)
    const finalFilter = {
      ...searchTextQuery,
      ...filterObj,
      ...querySearch,
      page: current,
      page_size: pageSize
    }
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({ pathname: location.pathname, search: searchQuery })
    this.setState({
      policy_number: false,
      claim_no: false,
      application_no: false,
      onSearchQuery: finalFilter,
      searchTextQuery: finalFilter,
      filteredInfo: {
        ...filterObj
      },
      page: current,
      page_size: pageSize
    }, () => this.fetch(finalFilter))
  }

  handleDownloadExcel = () => {
    const { userEmail, claimsFilter } = this.state
    swal({
      title: 'Report will be sent to your email',
      input: 'email',
      inputValue: userEmail,
      showCancelButton: true,
      confirmButtonText: 'Send',
      showLoaderOnConfirm: true,
      preConfirm: mail => {
        this.props.exportClaimsReport({
          body: {
            email: mail,
            ...claimsFilter
          }
        })
      },
      allowOutsideClick: () => false
    })
  }

  showGoPassengerClaimModal = (product) => {
    this.props.resetReduxStateClaim(['orderResult', 'orderStatus'])
    this.props.resetLoadingRedux(['GET_USER_PROFILE'])
    this.props.resetErrorRedux(['GET_USER_PROFILE'])
    this.setState({ showGoPassengerClaimModal: true, gojekProduct: product })
  }

  handleCloseGoPassengerClaimModal = () => {
    this.setState({ showGoPassengerClaimModal: false })
  }

  handleSearch = (value, key) => {
    const { history, location } = this.props
    const { searchTextQuery } = this.state
    const finalFilter = {
      ...searchTextQuery,
      [key]: value
    }
    this.fetch({
      ...finalFilter
    })
    const searchQuery = QuerySearchBuilder(finalFilter)
    history.push({ pathname: location.pathname, search: searchQuery })
  }

  getColumnProps (key) {
    return helperGetColumnProps(this, key)
  }

  getOwnerColumnProps (key) {
    return helperGetOwnerColumnProps(this, key)
  }

removeFilter = (key) => {
  const { history, location } = this.props
  const { claimsFilter } = this.state

  delete claimsFilter[key]
  this.setState({ claimsFilter })
  const searchQuery = QuerySearchBuilder(claimsFilter)
  history.push({ pathname: location.pathname, search: searchQuery })
  // Build params from the updated claimsFilter (post-deletion) and call filters API
  // If both productKey and packageName are cleared, reset filters to defaults
  if (!claimsFilter.partnerproduct_id && !claimsFilter.package_name) {
    // nothing left: fetch default filters
    this.props.getClaimFilters()
  } else {
    // For any other case (product removed, package removed, or one remains), delegate to helper
    helperFetchFiltersFromClaimsFilter(this, claimsFilter)
  }

  this.fetch(claimsFilter)
}

  createClaim = () => {
    const { payload } = this.state
    payload.source = 'control-panel'
    this.props.postGoPassengerClaim(payload)
  }

  validateClaim = payload => {
    this.setState({ payload })
    this.props.validateClaimGoPassenger(payload)
  }

  resetValidateStatus = () => {
    this.setState({ validateClaimGoPassengerStatus: '', displayLimitAlert: false })
    this.props.resetValidateStatus()
  }

  resetSafeScreen = () => {
    this.setState({ resetSafeScreen: false })
  }

  getRowColour = () => {
    const { claimsFilter } = this.state
    const colour = claimsFilter.colour

    switch (colour) {
      case 'RED':
        return '#ffd8d8'
      case 'YELLOW':
        return '#ffffd8'
      case 'GREEN':
        return '#e2ffe2'
      default:
        return '#fff'
    }
  }

  getProductNamefromKey (key) {
    return helperGetProductNamefromKey(this, key)
  }

  render () {
    const { getClaimListsLoading, getClaimListsError, data: ClaimsListData, permissions } = this.props
    const { claimsFilter, showGoPassengerClaimModal } = this.state
    const { meta_data: metaData = {}, data = [] } = ClaimsListData
    const { total_records: totalRecords = 0, page = 1 } = metaData
    const claimsList = data

    const columns = getClaimColumns(this)
    return (
      <LayoutContentWrapper
        className='referral-table'
        style={{
          color: '#788195'
        }}
      >
        <GoPassengerClaimModal
          isOpen={showGoPassengerClaimModal}
          onClosePopupForm={this.handleCloseGoPassengerClaimModal}
          validate={this.validateClaim}
          validateClaimGoPassengerStatus={this.state.validateClaimGoPassengerStatus}
          gojekProduct={this.state.gojekProduct}
          resetValidateStatus={this.resetValidateStatus}
          displaySafeScreen={this.state.displaySafeScreen}
          resetSafeScreen={this.resetSafeScreen}
          validatePopupMessage={this.state.validatePopupMessage}
          displayLimitAlert={this.state.displayLimitAlert}
          {...this.props}
        />
        <Row
          style={{
            width: '100%'
          }}
        >
          <Col>
            <FailedFetchAlert
              status='error'
              isNeedDisplay={this.state.failedMessage !== ''}
              onClose={this.handleResetReduxState}
              message={this.state.failedMessage}
            />
          </Col>
        </Row>
        <LayoutContent>
          <Row
            style={{
              marginBottom: '10px'
            }}
            align='middle'
          >
            <div>
              <h3
                style={{
                  float: 'left',
                  color: '#788195'
                }}
              >
                Claim Lists
              </h3>
              <div>
                <p
                  style={{
                    float: 'left',
                    color: '#4482FF',
                    marginLeft: '10px',
                    marginTop: '3px'
                  }}
                >
                  {totalRecords}
                </p>
              </div>
            </div>
            {
              Object.keys(claimsFilter).length > 0 &&
              Object.keys(claimsFilter).map(filterKey =>
                <Tag
                  key={claimsFilter}
                  style={{
                    alignSelf: 'center',
                    marginLeft: '5px',
                    paddingLeft: 4,
                    paddingRight: 4
                  }}
                  color='volcano'
                >
                  {filterKey === 'partnerproduct_id' ? 'product_name' : filterKey} - {filterKey === 'partnerproduct_id' ? this.getProductNamefromKey(claimsFilter[filterKey]) : claimsFilter[filterKey]}
                  <span className='remove-filter' onClick={() => this.removeFilter(filterKey)}>X</span>
                </Tag>
              )
            }
            <div
              style={{
                float: 'right',
                display: 'flex'
              }}
            >
              <Button onClick={this.handleResetFilter}>
                <Icon type='filter' theme='outlined' />
                &nbsp;Clear filter
              </Button>
              <div
                span={permissions !== undefined && permissions.length > 0 && permissions.indexOf('ops.download_claims_list') > -1 ? 8 : 3}
              >
                <div
                  style={{
                    display: 'flex',
                    float: 'right'
                  }}
                >
                  <PermissionChecker
                    permissionSetter='ops.download_claims_list'
                    permissionGetter={permissions}
                  >
                    <Button
                      onClick={this.handleDownloadExcel}
                      style={{
                        marginLeft: '10px'
                      }}
                    >
                      <Icon type='cloud' theme='outlined' />
                      &nbsp;Download
                    </Button>
                  </PermissionChecker>
                </div>
              </div>
              <div
                span={permissions.indexOf('ops.create_go_passenger_claim') > -1 ? 8 : 3}
              >
                <div
                  style={{
                    display: 'flex',
                    float: 'right'
                  }}
                >
                  <PermissionChecker
                    permissionSetter='ops.create_go_safe_trip'
                    permissionGetter={permissions}
                  >
                    <Button
                      onClick={() => this.showGoPassengerClaimModal('go_jek')}
                      style={{
                        marginLeft: '10px'
                      }}
                    >
                      <Icon type='highlight' theme='outlined' />
                      &nbsp; Create Safetrip Aus
                    </Button>
                  </PermissionChecker>
                  <PermissionChecker
                    permissionSetter='ops.create_go_passenger_claim'
                    permissionGetter={permissions}
                  >
                    <Button
                      onClick={() => this.showGoPassengerClaimModal('go_jek')}
                      style={{
                        marginLeft: '10px'
                      }}
                    >
                      <Icon type='highlight' theme='outlined' />
                      &nbsp; Create Go-Passenger Claim
                    </Button>
                  </PermissionChecker>
                  <PermissionChecker
                    permissionSetter='ops.create_go_driver_claim'
                    permissionGetter={permissions}
                  >
                    <Button
                      onClick={() => this.showGoPassengerClaimModal('go-driver')}
                      style={{
                        marginLeft: '10px'
                      }}
                    >
                      <Icon type='highlight' theme='outlined' />
                      &nbsp; Create Go-Driver Claim
                    </Button>
                  </PermissionChecker>
                </div>
              </div>
            </div>
          </Row>
          <TableWrapper
            bordered='bordered'
            columns={columns}
            pagination={{
              pageSize: 50,
              total: totalRecords,
              current: page
            }}
            rowKey={record => record.claim_id}
            dataSource={!getClaimListsError && !getClaimListsLoading ? claimsList : []}
            loading={getClaimListsLoading}
            className='isoSearchableTable'
            rowColor={this.getRowColour}
            onChange={this.handleTableChange}
          />
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

ClaimLists.propTypes = {
  claimUsers: PropTypes.array.isRequired,
  userProducts: PropTypes.array.isRequired
}

ClaimLists.defaultProps = {
  claimUsers: [],
  userProducts: []
}

export default connect(state => {
  return ({
    userProducts: state.Auth.product,
    data: state.Claims.data,
    filtersData: state.Claims.filtersData,
    getClaimListsStatus: state.Claims.getClaimListsStatus,
    profileData: state.Auth.profile,
    getClaimListsLoading: state.Loading.GET_CLAIM_LISTS,
    getClaimListsError: state.Error.GET_CLAIM_LISTS,
    getClaimsFiltersLoading: state.Loading.GET_CLAIM_FILTERS,
    getClaimsFiltersError: state.Error.GET_CLAIM_FILTERS,
    groupLists: state.Team,
    validateClaimGoPassengerStatus: state.Claims.validateClaimGoPassengerStatus,
    dataValidateGocar: state.Claims.dataValidateGocar,
    claimUsers: state.Claims.claimUsers,
    claimUsersStatus: state.Claims.claimUsersStatus,
    claimsUsersLoading: state.Loading.CLAIM_USERS,
    claimsUsersError: state.Error.CLAIM_USERS,
    claimExportLoading: state.Loading.EXPORT_CLAIMS_REPORT,
    claimExportError: state.Error.EXPORT_CLAIMS_REPORT,
    claimExportMessage: state.Claims.claimExportMessage
  })
}, {
  getClaimLists,
  getClaimFilters,
  resetReduxStateClaim,
  exportClaimsReport,
  resetLoadingRedux,
  resetErrorRedux,
  getListGroups,
  validateClaimGoPassenger,
  resetValidateStatus,
  postGoPassengerClaim,
  getClaimUsers,
  getPartners,
  getProducts
})(ClaimLists)
