import React from 'react'
import PermissionChecker from '../../../../components/permissionChecker'
import { ColumnSearchProps } from '../../../../components/SearchFilters'
import momentTimezone from 'moment-timezone'

// Build columns for ClaimLists. Pass the component instance (self) so we can call
// its helper methods (getColumnProps, getOwnerColumnProps, getPartnerColumnProps)
export default function getClaimColumns (self) {
  const { permissions } = self.props
  const { groups } = self.state
  const { profileData = {} } = self.props
  const userTimezone = profileData.user_timezone

  return [
    {
      key: 'Action',
      title: 'Action',
      dataIndex: 'claim_id',
      render: val => (
        <PermissionChecker
          permissionSetter='ops.view_claim_details'
          permissionGetter={permissions}
        >
          <i
            className='far fa-eye'
            onClick={() => self.detailPage(val)}
            style={{
              cursor: 'pointer'
            }}
          />
        </PermissionChecker>
      ),
      align: 'center'
    },
    {
      key: 'claim_no',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Claim id</span>
        </div>
      ),
      dataIndex: 'claim_no',
      ...self.getColumnProps('claim_number')
    },
    {
      key: 'policy_number',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Policy number</span>
        </div>
      ),
      dataIndex: 'policy_number',
      ...self.getColumnProps('policy_number')
    },
    {
      key: 'application_no',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Application no</span>
        </div>
      ),
      dataIndex: 'application_no',
      ...self.getColumnProps('application_no')
    },
    {
      key: 'owner_id',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Owner</span>
        </div>
      ),
      dataIndex: 'owner_id',
      ...self.getOwnerColumnProps('owner_id')
    },
    {
      key: 'partnerproduct_id',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Product Name</span>
        </div>
      ),
      dataIndex: 'display_name',
      ...ColumnSearchProps(self, 'partnerproduct_id', 'product', true)
    },
    {
      key: 'package_name',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Package name</span>
        </div>
      ),
      dataIndex: 'package_name',
      ...self.getColumnProps('package_name')
    },
    {
      key: 'status',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Status</span>
        </div>
      ),
      dataIndex: 'status',
      ...self.getColumnProps('status')
    },
    {
      key: 'benefit_slug',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Benefit</span>
        </div>
      ),
      dataIndex: 'benefit',
      ...self.getColumnProps('benefit_slug')
    },
    {
      key: 'partner_id',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Partner Id</span>
        </div>
      ),
      dataIndex: 'partner_id',
      ...self.getPartnerColumnProps('partner_id')
    },
    {
      key: 'claim_amount',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px', marginLeft: '20px' }}>
          <span>Claim Amount</span>
        </div>
      ),
      dataIndex: 'claim_amount',
      ...self.getColumnProps('claim_amount')
    },
    {
      key: 'created_at',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Created at</span>
        </div>
      ),
      dataIndex: 'created_at',
      render: (val) => ((val && userTimezone) ? momentTimezone.utc(val, 'DD/MM/YYYY HH:mm:ss').tz(userTimezone).format('DD/MM/YYYY HH:mm:ss') : '-'),
      ...self.getColumnProps('created_at')
    },
    {
      key: 'doc_complete_received_date',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Document Received Complete Date</span>
        </div>
      ),
      dataIndex: 'doc_complete_received_date',
      render: (val) => ((val && userTimezone) ? momentTimezone.utc(val, 'DD/MM/YYYY HH:mm:ss').tz(userTimezone).format('DD/MM/YYYY HH:mm:ss') : '-')
    },
    {
      key: 'accepted_at',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Accepted at</span>
        </div>
      ),
      dataIndex: 'accepted_at',
      render: (val) => (val ? momentTimezone.utc(val, 'DD/MM/YYYY HH:mm:ss').tz(userTimezone).format('DD/MM/YYYY HH:mm:ss') : '-'),
      ...self.getColumnProps('accepted_at')
    },
    {
      key: 'next_followup_date',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Next follow up date</span>
        </div>
      ),
      dataIndex: 'next_followup_date'
    },
    {
      key: 'Assign To',
      title: 'Assign To',
      dataIndex: 'owner_id',
      render: val => {
        return groups.map(values => {
          if (values.name === 'CLAIMS_TEAM') {
            return values.users.map(value => {
              if (val === String(value.id)) {
                return value.name
              }
              return null
            })
          }
          return null
        })
      },
      align: 'center'
    },
    {
      key: 'source',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Source</span>
        </div>
      ),
      dataIndex: 'source'
    },
    {
      key: 'type',
      title: (
        <div style={{ display: 'flex', paddingTop: '2px' }}>
          <span>Type</span>
        </div>
      ),
      dataIndex: 'type',
      ...self.getColumnProps('type')
    }
  ]
}
