import React, { Component } from 'react'
import { connect } from 'react-redux'
import { FilterTextStyle } from './index.style'
import { Input, Button, Select, DatePicker, Icon } from 'antd'

const { Option } = Select

class FilterText extends Component {
  state = {
    createdAtStart: '',
    createdAtEnd: ''
  }

  renderInputType = () => {
    const {
      props, type, searchKey, setSelectedKeys, selectedKeys, partnersList = [], productsList = [],
      partnerListLoading, productListLoading
    } = this.props
    const { createdAtStart, createdAtEnd } = this.state

    switch (type) {
      case 'partner':
        return <Select
          showSearch
          placeholder='Select Partner'
          optionFilterProp='children'
          allowClear
          loading={!!partnerListLoading}
          disabled={!!partnerListLoading}
          dropdownMatchSelectWidth={false}
          onChange={value => setSelectedKeys(value || '')}
          filterOption={(input, option) =>
            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {
            partnersList.map(({ name, code }) => <Option key={code} value={code}>{name}</Option>)
          }
        </Select>
      case 'product':
        return <Select
          showSearch
          placeholder='Select product'
          optionFilterProp='children'
          allowClear
          loading={!!productListLoading}
          disabled={!!productListLoading}
          dropdownMatchSelectWidth={false}
          onChange={value => setSelectedKeys(value || '')}
          filterOption={(input, option) =>
            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {
            productsList.map(({ display_name: displayName, id }) => <Option key={id} value={id}>{displayName}</Option>)
          }
        </Select>
      case 'date-range':
        return <div>
          <DatePicker
            placeholder='Select Start Date'
            onChange={(_, dateString) => {
              let date = `${dateString}`
              this.setState({ createdAtStart: date })
              setSelectedKeys(dateString ? [date, createdAtEnd] : [])
            }}
          />
          <DatePicker
            placeholder='Select End Date'
            className='range-end'
            onChange={(_, dateString) => {
              let date = `${dateString}`
              this.setState({ createdAtEnd: date })
              setSelectedKeys(dateString ? [createdAtStart, date] : [])
            }}
          />
        </div>
      default:
        return <Input
          ref={node => {
            props.searchInput = node
          }}
          placeholder={`Search ${searchKey}`}
          value={selectedKeys}
          onChange={e => setSelectedKeys(e.target.value ? e.target.value : '')}
          onPressEnter={() => props.handleSearch(selectedKeys, searchKey)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
    }
  }
  render () {
    const { props, searchKey, selectedKeys } = this.props

    return (
      <FilterTextStyle>
        {this.renderInputType()}

        <Button
          type='primary'
          onClick={() => props.handleSearch(selectedKeys, searchKey)}
          icon={<Icon type='search' />}
          className='search-button'
          size='small'
          style={{ width: 90 }}
        >
          Search
        </Button>
      </FilterTextStyle>
    )
  }
}

export default connect(state => ({
  partnerListLoading: state.Loading.GET_PARTNERS_LIST,
  partnersList: state.Insurance.partners,

  productListLoading: state.Loading.GET_PRODUCTS_LIST,
  productsList: state.Policy.products
}), {
})(FilterText)
