import React from 'react'
import { Icon, Select, Button } from 'antd'
import QueryString from 'query-string'
import { FilterInput, FilterDateRange, FilterSelect } from '../../../../components/tables/helperCells'

// Note: these helpers are written to accept the component instance (self)
// as the first argument so they can call instance methods (e.g. onSearch)

export function getColumnProps (self, key) {
  const fieldKeys = key
  const { filtersData, getClaimsFiltersLoading, getClaimsFiltersError, permissions, userProducts } = self.props
  const { filteredInfo } = self.state
  const filteredColor = filteredInfo[key]
    ? '#1890ff'
    : undefined
  const querySearch = QueryString.parse(self.props.location.search)
  if (!getClaimsFiltersLoading && !getClaimsFiltersError && Array.isArray(filtersData)) {
    if (!(permissions.indexOf('ops.claim_filter_product_name') > -1) && key === 'partnerproduct_id') { return {} }
    if (!(permissions.indexOf('ops.claim_filter_package_name') > -1) && key === 'package_name') { return {} }
    if (!(permissions.indexOf('ops.claim_status_filter') > -1) && key === 'status') { return {} }
    if (!(permissions.indexOf('ops.claim_created_date_filter') > -1) && key === 'created_at') { return {} }
    if (!(permissions.indexOf('ops.claim_date_filter') > -1) && key === 'accepted_at') { return {} }
    const keyFilterProp = filtersData.find(x => x.name === key)
    if (!keyFilterProp) { return {} }
    const filterType = keyFilterProp.type
    switch (filterType) {
      case 'choices':
      {
        const filterKeys = []
        if (key === 'product_key' && Array.isArray(userProducts) && !!userProducts.length) {
          for (key in userProducts) {
            filterKeys.push({ text: userProducts[key], value: userProducts[key] })
          }
        } else {
          const values = keyFilterProp.values || {}
          for (key in values) {
            filterKeys.push({ text: values[key], value: key })
          }
        }
        if (fieldKeys === 'partnerproduct_id') {
          return {
            filterIcon: (
              <Icon
                type='filter'
                style={{
                  color: filteredColor
                }}
              />
            ),
            filterDropdown: (
              <FilterSelect
                placeholder='Select Products'
                idIdentifier={fieldKeys}
                onInputChange={(e) => self.onInputProductChange(e, fieldKeys)}
                onSearch={self.handleProductSearch}
                enableButton={self.state.searchTextQuery && self.state.searchTextQuery[fieldKeys]}
                searchText={
                    self.state.isChange
                      ? self.state.searchTextQuery[fieldKeys]
                      : querySearch[fieldKeys] !== undefined
                        ? querySearch[fieldKeys]
                        : self.state.searchTextQuery[fieldKeys]
                  }
                selectData={filterKeys || []}
              />
            ),
            filterDropdownVisible: self.state[fieldKeys],
            onFilterDropdownVisibleChange: visible => self.setState({ [fieldKeys]: visible })
          }
        } else {
          return {
            filters: filterKeys,
            filterMultiple: keyFilterProp.multi_selection || false,
            filteredValue: filteredInfo[key] || null,
            filterIcon: (
              <Icon
                type='filter'
                style={{
                  color: filteredColor
                }}
              />
            )
          }
        }
      }
      case 'text': {
        return {
          filterIcon: (
            <Icon
              type='search'
              style={{
                color: self.state.searchTextQuery[key] || querySearch[key]
                  ? '#1890ff'
                  : undefined
              }}
            />),
          filterDropdown: (
            <FilterInput
              idIdentifier={key}
              searchText={self.state.isChange
                ? self.state.searchTextQuery[key]
                : querySearch[key] !== undefined
                  ? querySearch[key]
                  : self.state.searchTextQuery[key]}
              onInputChange={e => self.onInputChange(e, key)}
              onSearch={e => self.onSearch(e, key, filterType)}
            />
          ),
          filterDropdownVisible: self.state[key],
          onFilterDropdownVisibleChange: visible => self.setState({ [key]: visible })
        }
      }
      case 'date_range': {
        return {
          filterDropdown: (
            <FilterDateRange
              idIdentifier={key}
              onSearch={e => self.onSearch(e, key, filterType)}
              isClear={self.state.clearDate}
              startDate={self.state.isChange
                ? (self.state.searchTextQuery[key] || [])[0]
                : (querySearch[key] || [])[0] !== undefined
                    ? (querySearch[key] || [])[0]
                    : (self.state.searchTextQuery[key] || [])[0]}
              endDate={self.state.isChange
                ? (self.state.searchTextQuery[key] || [])[1]
                : (querySearch[key] || [])[1] !== undefined
                    ? (querySearch[key] || [])[1]
                    : (self.state.searchTextQuery[key] || [])[1]}
            />
          ),
          filterIcon: (
            <Icon
              style={{
                color: (self.state.searchTextQuery[key] !== undefined && self.state.searchTextQuery[key] !== undefined) || (querySearch[key] !== undefined && querySearch[key] !== undefined)
                  ? '#108ee9'
                  : '#aaa'
              }}
              type='filter'
              theme='outlined'
            />
          ),
          filterDropdownVisible: self.state[key],
          onFilterDropdownVisibleChange: visible => self.setState({ [key]: visible })
        }
      }
      case 'onselect_choices':
      {
        const filterKeys = []
        const values = keyFilterProp.values || {}
        for (key in values) {
          for (const value in values[key]) {
            filterKeys.push({ text: values[key][value], value })
          }
        }
        return {
          filters: filterKeys,
          filterMultiple: keyFilterProp.multi_selection || false,
          filteredValue: filteredInfo[key] || null,
          filterIcon: (
            <Icon
              type='filter'
              style={{
                color: filteredColor
              }}
            />
          )
        }
      }
      default:
        return {}
    }
  } else {
    return {}
  }
}

export function getOwnerColumnProps (self, key) {
  const { permissions, claimUsers } = self.props
  const { filteredInfo } = self.state

  if (!permissions.includes('ops.view_claims_list_owner_filter') && key === 'owner_id') return {}
  const filteredColor = filteredInfo[key] ? '#1890ff' : undefined
  const filteredValue = filteredInfo[key] ? [filteredInfo[key]] : null

  const filterKeys = claimUsers.map(({ id, name }) => ({ text: name, value: id }))

  return {
    filters: filterKeys,
    filterMultiple: false,
    filteredValue,
    filterIcon: (
      <Icon
        type='filter'
        style={{
          color: filteredColor
        }}
      />
    ),
    render: val => (
      <div>{(claimUsers.find(({ id }) => String(id) === val) || {}).name || val}</div>
    )
  }
}

export function getPartnerColumnProps (self, key) {
  const { filtersData, getClaimsFiltersLoading, getClaimsFiltersError } = self.props
  const { filteredInfo } = self.state

  if (getClaimsFiltersLoading || getClaimsFiltersError || !Array.isArray(filtersData)) {
    return {}
  }

  const filteredColor = filteredInfo[key] ? '#1890ff' : undefined

  const keyFilterProp = filtersData.find(x => x.name === key)
  if (!keyFilterProp) return {}

  const partnerOptions = []
  const values = keyFilterProp.values || {}

  for (const partnerId in values) {
    partnerOptions.push({
      name: values[partnerId],
      code: partnerId
    })
  }

  return {
    filterIcon: (
      <Icon
        type='filter'
        style={{ color: filteredColor }}
      />
    ),
    filterDropdown: ({ setSelectedKeys, selectedKeys }) => (
      <div className='filter-dropdown' style={{ padding: 8 }}>
        <Select
          showSearch
          placeholder='Select Partner'
          optionFilterProp='children'
          allowClear
          loading={self.props.getClaimsFiltersLoading}
          disabled={self.props.getClaimsFiltersLoading}
          dropdownMatchSelectWidth={false}
          value={selectedKeys}
          onChange={value => setSelectedKeys(value || '')}
          filterOption={(input, option) =>
            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
          style={{ width: 200, marginBottom: 8, display: 'block' }}
        >
          {partnerOptions.map(({ name, code }) => (
            <Select.Option key={code} value={code}>{name}</Select.Option>
          ))}
        </Select>
        <Button
          type='primary'
          onClick={() => self.handleSearch(selectedKeys, key)}
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
        <Button
          size='small'
          onClick={() => {
            setSelectedKeys('')
            self.handleSearch('', key)
          }}
        >
          Reset
        </Button>
      </div>
    ),
    filterDropdownVisible: self.state[key],
    onFilterDropdownVisibleChange: visible => self.setState({ [key]: visible })
  }
}

export function triggerFiltersWithKey (self, key, type) {
  const { filtersData, getClaimFilters } = self.props
  const { lastProductKeyRequested, lastPackageNameRequested } = self.state

  if (!filtersData || !key) {
    return
  }

  const name = type === 'product' ? self.getProductNamefromKey(key) : key

  const keyProp = filtersData?.find(x => x.name === (type === 'product' ? 'product_key' : 'package_name'))

  if (!keyProp) return

  const extractedKey = name

  const currentParams = extractedKey ? self.buildFilterParams(extractedKey, type) : {}

  // Determine whether to fetch: compare both productKey and packageName against last requested values
  const shouldFetch = (() => {
    if (!extractedKey) return false
    if (type === 'product') {
      // If product key changed OR package context changed compared to last request, fetch
      return (
        extractedKey !== lastProductKeyRequested ||
        (currentParams.packageName || null) !== (lastPackageNameRequested || null)
      )
    }
    // type === 'package'
    return (
      extractedKey !== lastPackageNameRequested ||
      (currentParams.productKey || null) !== (lastProductKeyRequested || null)
    )
  })()

  if (shouldFetch) {
    self.setState({
      isLoadingFilters: true,
      lastProductKeyRequested: currentParams.productKey || null,
      lastPackageNameRequested: currentParams.packageName || null
    })

    getClaimFilters(currentParams)
  } else if (!name) {
    // if no name provided, just refresh filters
    self.setState({ isLoadingFilters: true })
    getClaimFilters()
  }
}

export function buildFilterParams (self, extractedKey, type) {
  const { location } = self.props
  const currentPartnerProductId = getPartnerProductIdFromUrl(location?.search)
  const currentPackageName = getPackageNameFromUrl(location?.search)

  const params = {}

  if (type === 'product') {
    params.productKey = extractedKey
    if (currentPackageName) {
      params.packageName = currentPackageName
    }
  } else if (type === 'package') {
    params.packageName = extractedKey
    if (currentPartnerProductId) {
      const productKey = getProductNamefromKey(self, currentPartnerProductId)
      if (productKey) {
        params.productKey = productKey
      }
    }
  }

  return params
}

export function fetchFiltersFromClaimsFilter (self, claimsFilter) {
  if (!claimsFilter) return

  // productKey: prefer mapping from partnerproduct_id if present, otherwise use product_key
  const productKey = claimsFilter.partnerproduct_id
    ? self.getProductNamefromKey(claimsFilter.partnerproduct_id) || claimsFilter.product_key
    : claimsFilter.product_key

  const packageName = claimsFilter.package_name || null

  const params = {}
  if (productKey) params.productKey = productKey
  if (packageName) params.packageName = packageName

  // set loading and last requested keys so dedupe logic stays consistent
  self.setState({
    isLoadingFilters: true,
    lastProductKeyRequested: params.productKey || null,
    lastPackageNameRequested: params.packageName || null
  })

  self.props.getClaimFilters(params)
}

export function extractProductKeyFromId (self, partnerproductId) {
  const { filtersData } = self.props

  if (!filtersData || !partnerproductId) return null

  const productName = self.getProductNamefromKey(partnerproductId)
  const productKeyProp = filtersData?.find(x => x.name === 'product_key')

  if (productKeyProp && productName && productName.includes('-')) {
    return productKeyProp.values[
      productName.substring(productName.indexOf('-') + 1)
    ]
  }

  return null
}

export function getPartnerProductIdFromUrl (search) {
  if (!search) return null
  const match = search.match(/partnerproduct_id=([^&]+)/)
  return match ? match[1] : null
}

export function getPackageNameFromUrl (search) {
  if (!search) return null
  const match = search.match(/package_name=([^&]+)/)
  return match ? match[1] : null
}

export function getProductNamefromKey (self, key) {
  const { filtersData } = self.props
  if (filtersData) {
    const keyFilterProp = filtersData.find(x => x.name === 'partnerproduct_id')
    return keyFilterProp && keyFilterProp.values[key]
  }
}
